{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "PM2.5 over time, one line per sensor.",
  "mark": {
    "type": "line",
    "point": true
  },
  "encoding": {
    "x": {
      "field": "timestamp",
      "type": "temporal",
      "title": "Time"
    },
    "y": {
      "field": "pm25",
      "type": "quantitative",
      "title": "PM2.5"
    },
    "color": {
      "field": "sensor",
      "type": "nominal",
      "title": "Sensor"
    }
  }
}

readings, stations = arg[0], arg[1]

means = readings.groupby("sensor", as_index=False)["pm25"].mean()
return stations.merge(means, on="sensor")

{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Each station, sized by its mean PM2.5.",
  "mark": {
    "type": "circle",
    "opacity": 0.8
  },
  "encoding": {
    "longitude": {
      "field": "lon",
      "type": "quantitative"
    },
    "latitude": {
      "field": "lat",
      "type": "quantitative"
    },
    "size": {
      "field": "pm25",
      "type": "quantitative",
      "title": "Mean PM2.5"
    },
    "tooltip": [
      {
        "field": "name",
        "type": "nominal"
      },
      {
        "field": "pm25",
        "type": "quantitative",
        "format": ".1f"
      }
    ]
  }
}
